const PREPROCESS_SYSTEM = `You prepare search queries for a Russian pharmacy product enrichment pipeline.

Return ONLY valid JSON (no markdown) with this shape:
{
  "trade_name": "short trade name without dosage/pack if possible",
  "form_hint": "dosage form if present or null",
  "manufacturer_hint": "manufacturer if present or null",
  "queries": ["query1", "query2", "query3"]
}

Rules for queries (exactly 3 strings):
1. "{trade_name} МНН ГРЛС" (or INN / действующее вещество)
2. "{trade_name} рецептурный безрецептурный ГРЛС" (RX/OTC)
3. "{trade_name} инструкция применение возраст дети взрослые"

Do NOT classify the product. Do NOT invent clinical facts. Only rewrite the input into search queries.
Language of queries: Russian.`;

const item = $input.first().json || {};
let product = '';
let source = 'chat';

if (item.chatInput) {
  product = String(item.chatInput);
  source = 'chat';
} else if (item.body && (item.body.product || item.body.chatInput || item.body.text)) {
  product = String(item.body.product || item.body.chatInput || item.body.text);
  source = 'webhook';
} else if (item.product) {
  product = String(item.product);
  source = item.source || 'webhook';
} else if (item.text) {
  product = String(item.text);
  source = 'webhook';
}

product = product.trim();
if (!product) {
  throw new Error('Empty product name. Send chat message or POST {"product":"..."}.');
}

return [{
  json: {
    product,
    source,
    prompt_system: PREPROCESS_SYSTEM,
    prompt_user: `PRODUCT_INPUT:\n${product}\n\nReturn JSON only.`,
  },
}];

function extractJsonString(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'object') return JSON.stringify(value);
  let text = String(value).trim();
  const fence = text.match(/^```(?:json)?\s*\n?([\s\S]+?)\n?```\s*$/i);
  if (fence) text = fence[1].trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) text = text.slice(start, end + 1);
  return text;
}

const prep = $('Prepare Input').first().json;
const http = $input.first().json;
const raw = http.choices?.[0]?.message?.content ?? http.output ?? http.text ?? null;
const text = extractJsonString(raw);
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {};
}

const product = prep.product;
const trade = (parsed.trade_name && String(parsed.trade_name).trim()) || product.split('|')[0].trim();
let queries = Array.isArray(parsed.queries) ? parsed.queries.map((q) => String(q).trim()).filter(Boolean) : [];
if (queries.length === 0) {
  queries = [
    `${trade} МНН ГРЛС`,
    `${trade} рецептурный безрецептурный ГРЛС`,
    `${trade} инструкция применение возраст дети взрослые`,
  ];
}
queries = queries.slice(0, 3);

return queries.map((query, index) => ({
  json: {
    product,
    source: prep.source,
    trade_name: trade,
    form_hint: parsed.form_hint ?? null,
    manufacturer_hint: parsed.manufacturer_hint ?? null,
    query,
    query_index: index + 1,
    preprocess_raw: text,
    preprocess_model: http.model || null,
  },
}));

const POSTPROCESS_SYSTEM = `You extract structured pharmacy attributes ONLY from PRODUCT_INPUT and SEARCH_RESULTS.
It is forbidden to use your own knowledge, memory, or training data.
If a fact is not supported by SEARCH_RESULTS, use null / "not applicable" / "Other" as specified.

Return ONLY valid JSON (no markdown):
{
  "Category": "Drug" | "BAS" | "Other",
  "mnn": "name" | ["name1", "name2"] | null,
  "RX_OTC": "RX" | "OTC" | "not applicable",
  "Age": "Взрослый" | "Детский" | "Универсальный",
  "Text": "2-5 sentences in Russian citing what was found (include URLs when present)"
}

Field rules:
- Category:
  - Drug = лекарственное средство / препарат (ГРЛС, ЛС)
  - BAS = БАД / biologically active supplement
  - Other = гомеопатия, косметика, изделия, unclear, or insufficient evidence
- mnn: international nonproprietary name / МНН / действующие вещества.
  Combination products → array of component names.
  If not found in SEARCH_RESULTS → null
- RX_OTC:
  - RX = рецептурный
  - OTC = безрецептурный / отпускается без рецепта
  - not applicable = BAS/Other or no evidence in SEARCH_RESULTS
- Age:
  - Детский if kids/children/педиатрия is the primary target
  - Взрослый if adults only
  - Универсальный if both / not restricted / unclear from snippets
- Text: summarize ONLY from snippets; explicitly say what was missing if fields are null/not applicable.

Prefer official sources when they conflict: ГРЛС / rosminzdrav / instruction leaflets over marketplace blurbs.`;

const PREFERRED_HOST_RE = /(vidal\.ru|rlsnet\.ru|grls\.rosminzdrav\.gov\.ru|rosminzdrav|eisl\.roszdravnadzor|инструкция|medi\.ru|lsgeotar)/i;

function hostScore(url, title) {
  const s = `${url || ''} ${title || ''}`;
  if (PREFERRED_HOST_RE.test(s)) return 0;
  if (/apteka|uteka|asna|wildberries|ozon|market/i.test(s)) return 2;
  return 1;
}

function collectSnippets(httpItems, built) {
  const snippets = [];
  for (let i = 0; i < httpItems.length; i++) {
    const body = httpItems[i].json || {};
    const query = built[i]?.json?.query || body.query || '';
    const results = Array.isArray(body.results) ? body.results : [];
    for (const r of results.slice(0, 8)) {
      snippets.push({
        query,
        title: r.title || '',
        url: r.url || '',
        content: String(r.content || r.snippet || '').slice(0, 300),
        _score: hostScore(r.url, r.title),
      });
    }
  }
  snippets.sort((a, b) => a._score - b._score);
  return snippets.map(({ _score, ...rest }) => rest).slice(0, 16);
}

async function searxSearch(query) {
  try {
    const body = await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://127.0.0.1:8080/search',
      qs: { q: query, format: 'json', language: 'ru' },
      timeout: 30000,
      json: true,
    });
    return body && typeof body === 'object' ? body : { results: [] };
  } catch (e1) {
    try {
      const body = await this.helpers.httpRequest({
        method: 'GET',
        url: 'http://85.198.66.232:8080/search',
        qs: { q: query, format: 'json', language: 'ru' },
        timeout: 30000,
        json: true,
      });
      return body && typeof body === 'object' ? body : { results: [] };
    } catch (e2) {
      return { results: [], _error: String(e2) };
    }
  }
}

const httpItems = $input.all();
const built = $('Parse Queries').all();
const meta = built[0].json;
let snippets = collectSnippets(httpItems, built);
const usedQueries = built.map((b) => b.json.query);
const fallbackUsed = [];

// P1: fallback searches when too few hits
if (snippets.length < 3) {
  const trade = meta.trade_name || meta.product.split('|')[0].trim();
  const candidates = [
    `${trade} действующее вещество`,
    `${trade} МНН`,
    `${trade} инструкция по применению`,
  ].filter((q) => q && !usedQueries.includes(q));
  for (const q of candidates.slice(0, 2)) {
    const body = await searxSearch.call(this, q);
    fallbackUsed.push(q);
    const fakeBuilt = [{ json: { query: q } }];
    const extra = collectSnippets([{ json: body }], fakeBuilt);
    const seen = new Set(snippets.map((s) => s.url + '|' + s.title));
    for (const s of extra) {
      const key = s.url + '|' + s.title;
      if (!seen.has(key)) {
        snippets.push(s);
        seen.add(key);
      }
    }
    snippets.sort((a, b) => hostScore(a.url, a.title) - hostScore(b.url, b.title));
    snippets = snippets.slice(0, 16);
    if (snippets.length >= 3) break;
  }
}

const allQueries = usedQueries.concat(fallbackUsed);

if (snippets.length === 0) {
  return [{
    json: {
      product: meta.product,
      source: meta.source,
      trade_name: meta.trade_name,
      search_count: 0,
      search_queries: allQueries,
      fallback_queries: fallbackUsed,
      skip_llm: true,
      status: 'error',
      error_code: 'search_empty',
      error_message: 'SearXNG returned no usable snippets after primary and fallback queries.',
      retryable: true,
      Category: null,
      mnn: null,
      RX_OTC: 'not applicable',
      Age: 'Универсальный',
      Text: 'Поиск не вернул результатов. МНН не извлечён (fail-closed, без догадок модели).',
      ok_json: false,
      warnings: ['search_empty'],
    },
  }];
}

const searchBlock = snippets
  .map((s, idx) => `${idx + 1}. query=${s.query}\n   title=${s.title}\n   url=${s.url}\n   content=${s.content}`)
  .join('\n');

const prompt_user = [
  'PRODUCT_INPUT:',
  meta.product,
  '',
  `trade_name_guess: ${meta.trade_name}`,
  '',
  'SEARCH_RESULTS:',
  searchBlock,
  '',
  'Return JSON only. Use ONLY SEARCH_RESULTS.',
].join('\n');

return [{
  json: {
    product: meta.product,
    source: meta.source,
    trade_name: meta.trade_name,
    search_count: snippets.length,
    search_queries: allQueries,
    fallback_queries: fallbackUsed,
    skip_llm: false,
    prompt_system: POSTPROCESS_SYSTEM,
    prompt_user,
    evidence: snippets.map((s) => ({ url: s.url, title: s.title, query: s.query })),
  },
}];

function extractJsonString(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === 'object') return JSON.stringify(value);
  let text = String(value).trim();
  const fence = text.match(/^```(?:json)?\s*\n?([\s\S]+?)\n?```\s*$/i);
  if (fence) text = fence[1].trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) text = text.slice(start, end + 1);
  return text;
}

function normCategory(v) {
  if (v === null || v === undefined || v === '') return 'Other';
  const s = String(v).trim().toLowerCase();
  if (['drug', 'лс', 'лекарство', 'лекарственный препарат', 'лекарственное средство'].includes(s)) return 'Drug';
  if (['bas', 'bad', 'бад', 'баа'].includes(s)) return 'BAS';
  if (['other', 'иное', 'другое', 'гомеопатия'].includes(s)) return 'Other';
  return 'Other';
}

function normRx(v) {
  if (v === null || v === undefined || v === '') return 'not applicable';
  const s = String(v).trim().toLowerCase().replace(/\s+/g, ' ');
  if (['rx', 'рецептурный', 'по рецепту', 'prescription'].includes(s)) return 'RX';
  if (['otc', 'безрецептурный', 'без рецепта', 'otc-препарат'].includes(s)) return 'OTC';
  if (['not applicable', 'n/a', 'na', 'не применимо', 'unknown', 'неизвестно'].includes(s)) return 'not applicable';
  return 'not applicable';
}

function normAge(v) {
  if (v === null || v === undefined || v === '') return 'Универсальный';
  const s = String(v).trim().toLowerCase();
  if (s.includes('дет') || s.includes('child') || s.includes('kids') || s.includes('педиат')) return 'Детский';
  if (s.includes('взросл') || s.includes('adult')) return 'Взрослый';
  if (s.includes('универс') || s.includes('оба') || s.includes('любой')) return 'Универсальный';
  return 'Универсальный';
}

function normMnn(v) {
  if (v === null || v === undefined || v === '') return null;
  if (Array.isArray(v)) {
    const arr = v.map((x) => String(x).trim()).filter(Boolean);
    if (arr.length === 0) return null;
    if (arr.length === 1) return arr[0];
    return arr;
  }
  const s = String(v).trim();
  if (!s || s.toLowerCase() === 'null' || s === '-') return null;
  if (s.includes('+')) {
    const parts = s.split('+').map((p) => p.trim()).filter(Boolean);
    if (parts.length > 1) return parts;
  }
  return s;
}

const ctx = $('Aggregate Search').first().json;
const http = $input.first().json;
const alreadyRetried = Boolean(ctx._parse_retried || http._parse_retried);

// If Aggregate already short-circuited
if (ctx.skip_llm) {
  return [{ json: { ...ctx, needs_parse_retry: false } }];
}

const raw = http.choices?.[0]?.message?.content ?? http.output ?? http.text ?? null;
const rawText = extractJsonString(raw);
let parsed = null;
let ok = false;
let error = null;
try {
  parsed = JSON.parse(rawText);
  ok = parsed && typeof parsed === 'object' && !Array.isArray(parsed);
} catch (e) {
  error = String(e);
  parsed = {};
}

const Category = normCategory(parsed.Category ?? parsed.category);
const mnn = normMnn(parsed.mnn ?? parsed.MNN ?? parsed.inn);
const result = {
  Category,
  mnn,
  RX_OTC: normRx(parsed.RX_OTC ?? parsed.rx_otc ?? parsed.Rx_OTC),
  Age: normAge(parsed.Age ?? parsed.age ?? parsed.age_segment),
  Text: parsed.Text || parsed.text || '',
};

if (!result.Text || !String(result.Text).trim()) {
  result.Text = ok
    ? `Поиск вернул ${ctx.search_count} сниппетов.`
    : `Не удалось разобрать ответ модели. Raw: ${String(rawText || '').slice(0, 400)}`;
}

const warnings = [];
if (Array.isArray(ctx.fallback_queries) && ctx.fallback_queries.length) {
  warnings.push('used_fallback_queries');
}
let status = 'ok';
if (!ok) {
  status = 'error';
} else if (Category === 'Drug' && (mnn === null || mnn === '' || (Array.isArray(mnn) && mnn.length === 0))) {
  status = 'ok_partial';
  warnings.push('mnn_not_found');
}

const needs_parse_retry = (!ok) && !alreadyRetried;

return [{
  json: {
    ...result,
    text: JSON.stringify(result, null, 2),
    output: JSON.stringify(result, null, 2),
    product: ctx.product,
    source: ctx.source,
    search_count: ctx.search_count,
    search_queries: ctx.search_queries,
    fallback_queries: ctx.fallback_queries || [],
    evidence: ctx.evidence || [],
    validation_ok: ok,
    validation_error: error,
    ok_json: ok,
    status: needs_parse_retry ? 'error' : status,
    error_code: ok ? null : 'parse_error',
    error_message: ok ? null : (error || 'Model returned non-JSON or invalid object'),
    retryable: !ok,
    warnings,
    needs_parse_retry,
    prompt_system: ctx.prompt_system,
    prompt_user: ctx.prompt_user,
    postprocess_model: http.model || null,
    skip_llm: false,
  },
}];

const j = $input.first().json;
return [{
  json: {
    status: j.status,
    error_code: j.error_code,
    error_message: j.error_message,
    retryable: j.retryable,
    Category: j.Category,
    mnn: j.mnn,
    RX_OTC: j.RX_OTC,
    Age: j.Age,
    Text: j.Text,
    text: j.text || JSON.stringify({
      status: j.status, Category: j.Category, mnn: j.mnn, RX_OTC: j.RX_OTC, Age: j.Age, Text: j.Text, warnings: j.warnings,
    }, null, 2),
    output: j.output || j.text || '',
    search_count: j.search_count,
    ok_json: j.ok_json,
    warnings: j.warnings,
  },
}];

