}

const needs_parse_retry = (!ok) && !alreadyRetried;

return [{
  json: {
    ...result,
    text: JSON.stringify(result, null, 2),
    output: JSON.stringify(result, null, 2),
    product: ctx.product,
    source: ctx.source,
    search_count: ctx.search_count,
    search_queries: ctx.search_queries,
    fallback_queries: ctx.fallback_queries || [],
    evidence: ctx.evidence || [],
    validation_ok: ok,
    validation_error: error,
    ok_json: ok,
    status,
    error_code: ok ? null : 'parse_error',
    error_message: ok ? null : (error || 'Model returned non-JSON or invalid object'),
    retryable: !ok,
    warnings,
    needs_parse_retry: false,
    prompt_system: ctx.prompt_system,
    prompt_user: ctx.prompt_user,
    postprocess_model: http.model || null,
    skip_llm: false,
  },
}];

const j = $input.first().json || {};

function emptyMnn(m) {
  return m === null || m === undefined || m === '' || (Array.isArray(m) && m.length === 0);
}

const warnings = Array.isArray(j.warnings) ? [...j.warnings] : [];
let status = j.status || 'ok';
let error_code = j.error_code || null;
let error_message = j.error_message || null;
let retryable = Boolean(j.retryable);

if (j.skip_llm && j.error_code === 'search_empty') {
  status = 'error';
  error_code = 'search_empty';
  retryable = true;
} else if (error_code === 'parse_error' && !j.ok_json) {
  status = 'error';
  retryable = true;
} else if (j.ok_json !== false && j.Category === 'Drug' && emptyMnn(j.mnn)) {
  status = 'ok_partial';
  if (!warnings.includes('mnn_not_found')) warnings.push('mnn_not_found');
  error_code = null;
  error_message = null;
  retryable = false;
} else if (j.ok_json) {
  status = 'ok';
  error_code = null;
  error_message = null;
  retryable = false;
}

const out = {
  status,
  error_code,
  error_message,
  retryable,
  Category: j.Category ?? null,
  mnn: j.mnn ?? null,
  RX_OTC: j.RX_OTC ?? 'not applicable',
  Age: j.Age ?? 'Универсальный',
  Text: j.Text || '',
  search_count: j.search_count ?? 0,
  search_queries: j.search_queries || [],
  fallback_queries: j.fallback_queries || [],
  evidence: j.evidence || [],
  ok_json: Boolean(j.ok_json),
  warnings,
  product: j.product || null,
  source: j.source || null,
  postprocess_model: j.postprocess_model || null,
  text: j.text || '',
  output: j.output || j.text || '',
};

return [{ json: out }];

const item = $input.first().json || {};
const err = item.error || item;
const msg = String(err.message || item.message || JSON.stringify(item).slice(0, 500));
const desc = String(err.description || item.description || '');
const httpCode = String(err.httpCode || err.statusCode || item.httpCode || '');
const blob = `${msg} ${desc} ${httpCode}`.toLowerCase();

let error_code = 'llm_unavailable';
let retryable = true;
if (/unauthorized|authorization|api key|invalid_api_key|401|403/.test(blob)) {
  error_code = 'auth_failed';
  retryable = false;
} else if (/insufficient|balance|402|billing|quota/.test(blob)) {
